const assert = require('node:assert/strict');

const { EventService } = require('../.build/service');

// Original public behaviour: mapped records in order, lease closed once.
async function baseline() {
  let closes = 0;
  const values = ['a', 'b', null];
  const service = new EventService({
    open: async () => ({ read: async () => values.shift(), close: async () => { closes++; } }),
  });
  const found = [];
  for await (const value of service.stream()) found.push(value);
  assert.deepEqual(found, ['A', 'B']);
  assert.equal(closes, 1);
}

async function main() {
  await baseline();
  await require('./lifecycle.cjs');
}

module.exports = main();

