import { Lease, Source } from './source';
import { mapEvent } from './mapper';

export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  async *stream(): AsyncGenerator<string> {
    let lease: Lease | undefined;
    let failed = false;
    try {
      for (;;) {
        // The lease is opened lazily: only once the consumer actually asks for
        // the first record. A generator that is returned before its first
        // next() never reaches this line, so nothing is opened or closed.
        lease ??= await this.source.open();
        // Exactly one read per next(); the read that observes `null` is the
        // one that establishes exhaustion, so there is no read ahead.
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      // A read failure, a mapper failure or a consumer-injected throw reaches
      // this point; remember it so the finally block keeps it as the
      // propagated error even when closing also fails.
      failed = true;
      throw error;
    } finally {
      const pending = lease;
      lease = undefined;
      if (pending !== undefined) {
        if (failed) {
          // Preserve the original read/mapper/injected exception: a close
          // failure here must not mask it.
          try {
            await pending.close();
          } catch {
            // Swallowed on purpose; `error` continues to propagate.
          }
        } else {
          // Normal exhaustion or consumer break/return: there is no
          // underlying exception, so a close failure propagates.
          await pending.close();
        }
      }
    }
  }
}
